package com.bank.restkafka.rest;

import java.math.BigDecimal;
import java.util.Map;
import java.util.logging.Logger;

// REST: synchronous query. The caller NEEDS the number right now.
public class BalanceRestClient {
    private static final Logger log = Logger.getLogger(BalanceRestClient.class.getName());
    private final Map<String, BigDecimal> balances;
    public BalanceRestClient(Map<String, BigDecimal> balances) { this.balances = balances; }

    public BigDecimal getBalance(String accountId) {
        BigDecimal b = balances.get(accountId);
        log.info(() -> "REST GET /accounts/" + accountId + "/balance → " + b + " (blocking)");
        return b;   // caller waits
    }
    public void debit(String accountId, BigDecimal amount) {
        balances.put(accountId, balances.get(accountId).subtract(amount));
        log.info(() -> "REST POST debit " + amount + " from " + accountId);
    }
}
