package com.bank.restkafka.kafka;

import java.util.ArrayList;
import java.util.List;
import java.util.function.Consumer;
import java.util.logging.Logger;

// Kafka: durable async event log. Publish and return immediately; many consumers.
public class KafkaEventBus {
    private static final Logger log = Logger.getLogger(KafkaEventBus.class.getName());
    private final List<Consumer<String>> consumers = new ArrayList<>();
    private final List<String> log_ = new ArrayList<>();   // durable, replayable

    public void subscribe(Consumer<String> consumer) { consumers.add(consumer); }

    public void publish(String topic, String event) {
        log_.add(event);                                    // persisted (replayable)
        log.info(() -> "KAFKA send → '" + topic + "': " + event + " (producer does NOT wait)");
        for (Consumer<String> c : consumers) c.accept(event);
    }
    public List<String> replay() { return List.copyOf(log_); }
}
