package com.bank.restkafka.kafka;

import java.util.logging.Logger;
public class FraudConsumer {
    private static final Logger log = Logger.getLogger(FraudConsumer.class.getName());
    private boolean down = false;
    public void simulateOutage(boolean down) { this.down = down; }
    public void onEvent(String event) {
        if (down) { log.warning("FRAUD down — event waits in topic, transfer unaffected"); return; }
        log.info(() -> "FRAUD scores async → " + event);
    }
}
