package com.bank.restkafka.payment;

import com.bank.restkafka.kafka.KafkaEventBus;
import com.bank.restkafka.rest.BalanceRestClient;
import java.math.BigDecimal;
import java.util.logging.Logger;

// REST for the critical path (needs answer now), Kafka for the fact broadcast.
public class PaymentFacade {
    private static final Logger log = Logger.getLogger(PaymentFacade.class.getName());
    private final BalanceRestClient restClient;
    private final KafkaEventBus eventBus;

    public PaymentFacade(BalanceRestClient restClient, KafkaEventBus eventBus) {
            this.restClient = restClient;
            this.eventBus = eventBus;
    }

    public BigDecimal queryBalance(String accountId) {   // pure query → REST
        return restClient.getBalance(accountId);
    }

    public String transfer(String from, String to, BigDecimal amount) {
        BigDecimal balance = restClient.getBalance(from);          // REST: need it now
        if (balance.compareTo(amount) < 0) return "REJECTED_INSUFFICIENT_FUNDS";
        restClient.debit(from, amount);                            // REST: need confirmation
        log.info(() -> "Transfer done, responding immediately");
        eventBus.publish("payment-events",                         // Kafka: a fact happened
            "PAYMENT_COMPLETED from=" + from + " amount=" + amount);
        return "COMPLETED";
    }
}
