package com.bank.restkafka;

import com.bank.restkafka.kafka.FraudConsumer;
import com.bank.restkafka.kafka.KafkaEventBus;
import com.bank.restkafka.kafka.NotificationConsumer;
import com.bank.restkafka.payment.PaymentFacade;
import com.bank.restkafka.rest.BalanceRestClient;
import java.math.BigDecimal;
import java.util.HashMap;
import java.util.Map;
import java.util.logging.Logger;

public class RestVsKafkaDemo {
    private static final Logger log = Logger.getLogger(RestVsKafkaDemo.class.getName());

    public static void main(String[] args) {
        Map<String, BigDecimal> balances = new HashMap<>();
        balances.put("SAV2001", new BigDecimal("1000000"));
        balances.put("CUR3001", new BigDecimal("250000"));

        KafkaEventBus eventBus = new KafkaEventBus();
        NotificationConsumer notify = new NotificationConsumer();
        FraudConsumer fraud = new FraudConsumer();
        eventBus.subscribe(notify::onEvent);
        eventBus.subscribe(fraud::onEvent);

        PaymentFacade facade = new PaymentFacade(new BalanceRestClient(balances), eventBus);

        log.info("=== REST: immediate balance query ===");
        log.info("Balance: " + facade.queryBalance("SAV2001"));

        log.info("=== Hybrid transfer: REST critical path + Kafka broadcast ===");
        log.info("Result: " + facade.transfer("SAV2001", "CUR3001", new BigDecimal("50000")));

        log.info("=== Fraud consumer down: event waits, transfer still fine ===");
        fraud.simulateOutage(true);
        log.info("Result: " + facade.transfer("SAV2001", "CUR3001", new BigDecimal("30000")));
    }
}
